package com.friendoncampus.credit.service;
import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.*;import tools.jackson.databind.json.JsonMapper;
@org.springframework.boot.autoconfigure.condition.ConditionalOnBean(JdbcClient.class)
@Service public class CreditEvidenceExportService {private final JdbcClient db;private final JsonMapper json=JsonMapper.builder().build();public CreditEvidenceExportService(JdbcClient db){this.db=db;}@Transactional(readOnly=true)public Export read(UUID orderId,String cursor,int limit){if(limit<1||limit>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Limit must be between 1 and 100");long committed=db.sql("SELECT COALESCE(MAX(evidence_sequence),0) FROM credit_outbox_events WHERE aggregate_type='Order' AND aggregate_id=:id").param("id",orderId).query(Long.class).single();long missing=db.sql("SELECT count(DISTINCT o.id) FROM credit_operations o JOIN credit_ledger_entries l ON l.operation_id=o.id WHERE o.order_id=:id AND o.operation_type<>'ADMIN_CORRECTION' AND NOT EXISTS(SELECT 1 FROM credit_outbox_events e WHERE e.aggregate_type='Order' AND e.aggregate_id=:id AND e.payload_json::jsonb->>'operationId'=o.id::text)").param("id",orderId).query(Long.class).single();if(missing>0)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Credit ledger evidence baseline is incomplete");long pinned=committed;int offset=0;if(cursor!=null)try{String[]p=new String(Base64.getUrlDecoder().decode(cursor),StandardCharsets.UTF_8).split(":");if(p.length!=2)throw new IllegalArgumentException();pinned=Long.parseLong(p[0]);offset=Integer.parseInt(p[1]);if(pinned<0||pinned>committed||offset<0||offset>pinned)throw new IllegalArgumentException();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid cursor");}var rows=db.sql("SELECT event_id,event_type,evidence_sequence,occurred_at,actor_json,payload_json,created_at FROM credit_outbox_events WHERE aggregate_type='Order' AND aggregate_id=:id AND evidence_sequence<=:p ORDER BY evidence_sequence").param("id",orderId).param("p",pinned).query((rs,n)->new Row(rs.getObject(1,UUID.class),rs.getString(2),rs.getLong(3),rs.getObject(4,OffsetDateTime.class),rs.getString(5),rs.getString(6),rs.getObject(7,OffsetDateTime.class))).list();if(rows.size()!=pinned)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"A trustworthy Credit evidence baseline is unavailable");List<Map<String,Object>> records=new ArrayList<>();for(Row row:rows){JsonNode p=json.readTree(row.payload);UUID operation=UUID.fromString(p.path("operationId").asText());var entries=db.sql("SELECT id,account_id,available_delta,reserved_delta,available_balance_after,reserved_balance_after FROM credit_ledger_entries WHERE operation_id=:id ORDER BY created_at,id").param("id",operation).query((rs,n)->Map.<String,Object>of("ledgerEntryId",rs.getObject(1,UUID.class),"userId",rs.getObject(2,UUID.class),"availableDelta",rs.getInt(3),"reservedDelta",rs.getInt(4),"availableBalance",rs.getInt(5),"reservedBalance",rs.getInt(6))).list();Map<String,Object>d=new LinkedHashMap<>();d.put("kind","CREDIT");d.put("operationId",operation);d.put("ledgerEntries",entries);d.put("reasonCode",p.path("reasonCode").asText(null));d.put("result",row.type.endsWith("Rejected")?"REJECTED":entries.isEmpty()?"NO_CHANGE":"APPLIED");Map<String,Object>r=new LinkedHashMap<>();r.put("eventId",row.id);r.put("source","credit-service");r.put("stream","credit.events");r.put("sourceSequence",row.sequence);r.put("orderId",orderId);r.put("action",row.type);r.put("actorUserId",null);r.put("occurredAt",row.occurredAt);r.put("ingestedAt",row.createdAt);r.put("data",d);records.add(r);}int end=Math.min(offset+limit,records.size());String next=end<records.size()?Base64.getUrlEncoder().withoutPadding().encodeToString((pinned+":"+end).getBytes(StandardCharsets.UTF_8)):null;return new Export(orderId,"credit-"+orderId+"-"+pinned,new Checkpoint("credit-service","credit.events",orderId,pinned,Instant.now()),records.subList(offset,end),next);}private record Row(UUID id,String type,long sequence,OffsetDateTime occurredAt,String actor,String payload,OffsetDateTime createdAt){}public record Checkpoint(String source,String stream,UUID aggregateId,long committedSequence,Instant checkedAt){}public record Export(UUID orderId,String snapshotId,Checkpoint checkpoint,List<Map<String,Object>> records,String nextCursor){}}
